import React, { useState } from 'react';
import {
  MicIcon,
  MicOffIcon,
  VideoIcon,
  VideoOffIcon,
  ScreenShareIcon,
  CaptionsIcon,
  RecordIcon,
  PhoneOffIcon,
  EmojiHappyIcon,
} from './Icons';

export const CallControls = ({
  isMuted,
  setIsMuted,
  isVideoOff,
  setIsVideoOff,
  isScreenSharing,
  toggleScreenShare,
  showCaptions,
  setShowCaptions,
  sendReaction,
  isRecording,
  setIsRecording,
  onEndCall,
}) => {
  const [isReactionsOpen, setReactionsOpen] = useState(false);

  const reactions = ['👍', '❤️', '🎉', '😂'];

  return (
    <div className="relative">
      {/* Reactions Popup */}
      {isReactionsOpen && (
        <div className="absolute bottom-full mb-4 left-1/2 transform -translate-x-1/2 bg-gray-800/95 backdrop-blur-sm rounded-2xl px-6 py-4 flex gap-4 shadow-2xl border border-gray-700">
          {reactions.map((emoji) => (
            <button
              key={emoji}
              onClick={() => {
                sendReaction(emoji);
                setReactionsOpen(false);
              }}
              className="text-3xl hover:scale-150 transition-transform duration-200"
            >
              {emoji}
            </button>
          ))}
        </div>
      )}

      {/* Main Control Bar */}
      <div className="flex items-center gap-3 bg-gray-800/90 backdrop-blur-md px-6 py-4 rounded-full shadow-2xl border border-gray-700">
        {/* Mic (WebRTC mute/unmute) */}
        <button
          onClick={() => setIsMuted(!isMuted)}
          className={`p-4 rounded-full transition-all ${
            isMuted
              ? 'bg-red-600 hover:bg-red-700 shadow-lg shadow-red-500/50'
              : 'bg-gray-700 hover:bg-gray-600'
          }`}
          title={isMuted ? 'Unmute microphone' : 'Mute microphone'}
        >
          {isMuted ? (
            <MicOffIcon className="w-6 h-6 text-white" />
          ) : (
            <MicIcon className="w-6 h-6 text-white" />
          )}
        </button>

        {/* Camera */}
        <button
          onClick={() => setIsVideoOff(!isVideoOff)}
          className={`p-4 rounded-full transition-all ${
            isVideoOff
              ? 'bg-red-600 hover:bg-red-700 shadow-lg shadow-red-500/50'
              : 'bg-gray-700 hover:bg-gray-600'
          }`}
          title={isVideoOff ? 'Turn camera on' : 'Turn camera off'}
        >
          {isVideoOff ? (
            <VideoOffIcon className="w-6 h-6 text-white" />
          ) : (
            <VideoIcon className="w-6 h-6 text-white" />
          )}
        </button>

        {/* Screen share */}
        <button
          onClick={toggleScreenShare}
          className={`p-4 rounded-full transition-all ${
            isScreenSharing
              ? 'bg-green-600 hover:bg-green-700 shadow-lg shadow-green-500/50'
              : 'bg-gray-700 hover:bg-gray-600'
          }`}
          title={isScreenSharing ? 'Stop screen share' : 'Share screen'}
        >
          <ScreenShareIcon className="w-6 h-6 text-white" />
        </button>

        {/* Captions */}
        <button
          onClick={() => setShowCaptions(!showCaptions)}
          className={`p-4 rounded-full transition-all ${
            showCaptions
              ? 'bg-blue-600 hover:bg-blue-700'
              : 'bg-gray-700 hover:bg-gray-600'
          }`}
          title={showCaptions ? 'Hide captions' : 'Show captions'}
        >
          <CaptionsIcon className="w-6 h-6 text-white" />
        </button>

        {/* Record */}
        <button
          onClick={() => setIsRecording(!isRecording)}
          className={`p-4 rounded-full transition-all ${
            isRecording
              ? 'bg-red-600 hover:bg-red-700 animate-pulse shadow-lg shadow-red-500/50'
              : 'bg-gray-700 hover:bg-gray-600'
          }`}
          title={isRecording ? 'Stop recording' : 'Start recording'}
        >
          <RecordIcon className="w-6 h-6 text-white" />
        </button>

        {/* Reactions */}
        <button
          onClick={() => setReactionsOpen(!isReactionsOpen)}
          className="p-4 rounded-full bg-gray-700 hover:bg-gray-600 transition-all"
          title="Send reaction"
        >
          <EmojiHappyIcon className="w-6 h-6 text-white" />
        </button>

        {/* End call */}
        <button
          onClick={onEndCall}
          className="p-4 rounded-full bg-red-600 hover:bg-red-700 transition-all shadow-lg shadow-red-500/50"
          title="End call"
        >
          <PhoneOffIcon className="w-6 h-6 text-white" />
        </button>
      </div>
    </div>
  );
};
